def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to remove build metadata
        v_without_metadata = v.split('+')[0]

        # Split by '-' to separate base version and pre-release
        if '-' in v_without_metadata:
            base_part, prerelease_part = v_without_metadata.split('-', 1)
        else:
            base_part = v_without_metadata
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            # Convert each identifier: numeric stays int, others stay string
            parsed_identifiers = []
            for ident in identifiers:
                if ident.isdigit():
                    parsed_identifiers.append((0, int(ident)))
                else:
                    parsed_identifiers.append((1, ident))
        else:
            parsed_identifiers = None

        return (major, minor, patch, parsed_identifiers)

    def compare_key(v):
        major, minor, patch, identifiers = parse_version(v)

        # For sorting: (major, minor, patch, has_prerelease_tuple)
        # If identifiers is None (no prerelease), it should sort after same version with prerelease
        # So we use a tuple where no prerelease sorts after
        if identifiers is None:
            # No prerelease: sorts after same version with prerelease
            prerelease_key = (1,)  # Higher tuple sorts later
        else:
            # Has prerelease: sorts before same version without prerelease
            prerelease_key = (0, tuple(identifiers))

        return (major, minor, patch, prerelease_key)

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=compare_key)

